import Root from "./2Managing State/3PreserrvingandResetting"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useState } from "react"

export default function() {
  const [counter, setCounter] = useState(0)
  const [notin, setNotin] = useState(false)
 return <>
 <button onClick={() => {setNotin(!notin)}}>{notin.toString()}</button>
 {notin ? (<Count key={true} setCounter={setCounter} counter={counter} truefalse={notin}/>) : (<Count key="2" truefalse={notin} setCounter={setCounter} counter={counter}/>)}
 </>
}

function Count({setCounter, counter, truefalse}) {
  return <> <br/>
  <button onClick={() => {setCounter(counter+1)}}>{counter}</button>
  <p>{truefalse.toString()}</p>
  </>

}

